    faq_a_bag_examples_list: "Uuden laukun mukana tulee esimerkkejä, joita voi muuttaa tai poistaa kuten mitä tahansa muuta: Koti (ostokset, reseptit, viikon ateriat), Perhe (pienet hetket, synttärijuhlien lista, harrastukset ja kerhot), Ideat (viikonloppuideat, lahjaideat kategorioittain, ja mitä tehdä säästetyillä rahoilla) ja Matkat (paikat, joihin haluat mennä, matkan pakkauslista, hotellin pakkauslista ja lista lennolle ulkomaille). Jo olemassa olevaan laukkuun tulevat uusimmat kerran, sen omiin taskuihin.",
