    faq_a_shop_holidays: "Napauta Ostoslistassa lahjaa: maasi (Asetuksissa valitun maan) juhlapyhät näkyvät järjestyksessä päivämäärineen – ne lasketaan joka vuosi itsestään. Napauta juhlaa, niin saat valmiin listan siitä, mitä siihen tavallisesti ostetaan; kaikki on valittuna (paitsi se, mikä on jo listallasi), poista valinta siitä, mitä et tarvitse, ja napauta ”Lisää listalle”. Kaksi viikkoa ennen juhlaa listan yläreunaan tulee pieni kortti; ✕ piilottaa sen seuraavaan juhlaan asti.",
    faq_q_shop_holidays: "Miten ”Mitä ostaa juhlaan” toimii?",
    shop_hol_add: "Lisää listalle ({n})",
    shop_hol_added: "Lisätty listalle: {n}",
    shop_hol_btn: "Mitä ostaa juhlaan",
    shop_hol_items_title: "{holiday} – mitä ostaa?",
    shop_hol_not_now: "Ei nyt",
    faq_a_shop_delivery: "Napauta Ostoslistassa kuorma-autoa: valitse, mitä toimituksessa on (kaikki on valittuna), milloin se tulee – tänään, huomenna vai muuna päivänä – ja mihin aikaan (aamu, päivä, ilta tai ”Muu…”, jos haluat omat kellonajat). Nämä tuotteet siirtyvät listan yläreunan ”Matkalla”-kortille päivän ja kellonaikojen kanssa. Kun päivä koittaa, Päiväni-näkymään tulee ”Tuliko toimitus?” (ja kortissa on ”Tuliko?”). Jos kaikki tuli, tuotteet siirtyvät ”Osta uudelleen” -kohtaan. Jos jotain puuttuu, napauta sitä, mikä ei tullut, niin se palaa suoraan listalle.",
    faq_a_shop_departments: "Lista järjestyy itsestään kaupan osastojen mukaan – hedelmät ja vihannekset, leipä, maitotuotteet ja munat, liha ja kala, kuivatuotteet, pakasteet, juomat, naposteltavat, siivous, hygienia, vauvat ja lemmikit – joten kuljet käytävät järjestyksessä. Osasto tunnistetaan tuotteen nimestä. Jos tuote päätyi väärään paikkaan, napauta sitä ja valitse sen osasto tai ”Muu…”, niin voit kirjoittaa oman.",
    faq_a_shop_share_qty: "Voit. Jokaisen tuotteen vieressä + lisää yhden (×2, ×3…) ja − vähentää yhden. Ostoslistan yläreunan jakopainike lähettää koko listan osastoittain siististi järjestettynä WhatsAppissa, sähköpostilla tai kopiona.",
    faq_a_shop_two_buttons: "Molemmat tarkoittavat ”ostettu”. ✕ on asioille, jotka ostat kerran – tuote lähtee listalta (ja odottaa 🗑️-arkistossa siltä varalta, että se oli vahinko). ↺ on asioille, joita ostat yhä uudelleen – tuote lähtee listalta ja odottaa ”Osta uudelleen” -kohdassa: sen avaa pieni ↺-painike roskakorin vieressä listan alareunassa, ja yksi napautus siellä palauttaa tuotteen listalle. Sen ”Muokkaa”-kohdasta voit poistaa tuotteen sieltä. Kun lisäät tuotteen, aiemmin ostamasi asiat näkyvät ehdotuksina, ja jos tuote on jo listalla, siitä tulee vain ×2 eikä toista riviä.",
