    nm_demo_title: "Näin vaihto toimii",
    faq_a_new_me_challenge_journal: "Kun haaste päättyy – iso, mini tai viikon haaste – juhlahetkessä on painike 📝 Miten meni?, joka avaa sivun haastepäiväkirjaan: miltä tuntui (viisi kasvoa), mikä auttoi, mikä oli vaikeaa ja mitä otan mukaani – mikään ei ole pakollista, ja sen voi tehdä myöhemminkin. Päiväkirja on timantti taikarepussa: jokainen suoritettu haaste päivämäärineen ja kirjoituksineen, uusin ensin – napauta yhtä lukeaksesi, muokataksesi tai jakaaksesi sen (vain sivulla oleva jaetaan). Suoritettu haaste saa myös mitalin saavutuksiin, kohtaan ”Suorittamani haasteet”. Haastepäiväkirja on erillään tavallisesta päiväkirjasta.",
    faq_q_new_me_challenge_journal: "Mikä on haastepäiväkirja?",
