    nm_chj_q: "Miten haaste meni?",
    nm_chj_reflect_btn: "Miten meni?",
    nm_chj_save: "Tallenna haastepäiväkirjaan",
    nm_chj_saved: "Tallennettu haastepäiväkirjaan",
    nm_chj_share_text: "Suoritin haasteen New Me -ohjelmassa ✨",
    nm_chj_take: "Mitä otan mukaani?",
    nm_chj_title: "Haastepäiväkirja",
    nm_chj_write: "Kirjoita, miten meni",
    nm_swap_time: "Aika",
    faq_a_ai_reminder_in_text: "Kyllä – kirjoita se tehtävän kanssa, esimerkiksi ”huomenna klo 17:00 paketin nouto, muistutus tuntia ennen”. Muistutus tallentuu itse tehtävään: tuntia ennen, puoli tuntia, päivää ennen ja niin edelleen, ja ”muistuta minua” ilman aikaa tarkoittaa 10 minuuttia ennen. Tekstiin kirjoitettu muistutus menee saman ikkunan muistutuskentän edelle.",
    faq_q_ai_reminder_in_text: "Voinko pyytää AI-avustajalta muistutusta samassa pyynnössä?",
    myday_meals_all_done: "Kaikki tämän päivän ateriat on merkitty 🍽️",
    nm_tour_week_text: "Pieni haaste viikolle. ✓ joka päivä – lopuksi avain.",
    books_home_chip: "{title} · s. {page}",
    books_home_of: "/ {total}",
    books_home_off_toast: "Kirja poistui aloitusnäytöltä",
    books_home_on_toast: "Kirja on aloitusnäytöllä 📖",
    books_home_pin: "Aloitusnäytöllä",
    books_home_q: "Millä sivulla olen?",
    books_home_save: "Tallenna",
    faq_a_books_home_chip: "Kyllä. Lukunurkkauksessa napauta parhaillaan lukemasi kirjan kortissa 📌 Aloitusnäytöllä. Aloitusnäytölle tervehdyksen alle ilmestyy pieni painike, jossa on kirja ja sivu – napauta sitä, kirjoita uusi sivunumero ja tallenna, niin edistymistä seurataan (myös Lukunurkkauksessa). Napauttamalla 📌 uudelleen se poistuu. Siellä voi olla useita kirjoja yhtä aikaa – jokaiselle oma painike – ja se on sama kaikilla laitteilla.",
    faq_a_new_me_week_challenge: "Pieni haaste yhdeksi viikoksi, jonka valitset itse. Käytävällä on iso kortti: ”Minkä parissa haluat työskennellä tällä viikolla?” – napauta sitä, valitse alue (itseni kanssa, muiden kanssa, oppiminen ja kasvu, rauha, pienet rohkeat askeleet, koti ja rutiinit) ja haaste, ja valitse, milloin se alkaa. Samat haasteet löytyvät myös haasteet-näytöstä kohdasta 🌱 Henkilökohtainen kasvu. Joka päivä merkitset kortille ✓ (yksi vapaapäivä viikossa), ja jokainen päättyvä viikko tuo uuden avaimen salaiseen maailmaan. ”Lue 2 sivua päivässä” merkitään itsestään Lukunurkkaukseen kirjatuista sivuista. Kun viikko päättyy, 📌 Pidä päivittäisenä tehtävänä lisää sen kohtaan Rutiinini valitsemaasi aikaan, ✓ joka päivä. Kerrallaan on käynnissä yksi viikon haaste; isot haasteet ja minihaasteet jatkuvat sen rinnalla.",
    faq_a_room_genie: "Kuistilla meren rannalla Aladdinin lampun napautus nostaa esiin metsänhengen – ja keskustelu alkaa: mikä on toiveesi (mitä haluaisit muuttaa elämässäsi), miltä se tuntuu, kun se toteutuu, mikä on vaikeaa matkalla ja miten nykyinen tilanne voidaan kääntää hyväksi. Sitten suunnilleen kuinka kauan se kestää, ensimmäinen pieni askel ja kaksi lisää sekä ”jos… niin…” hetkiin, kun on vaikeaa. Lopuksi koko toive näkyy askel askeleelta, ja siitä voi tehdä tavoitteen kohtaan Omat Tavoitteet (askeleista tulee polun vaiheita, päivämäärineen valitun ajan mukaan; siellä kaikkea voi muuttaa) tai tallentaa sen päiväkirjaan – ja sitten metsänhenki hyvästelee. Mitään ei tallenneta, ellei valitse jompaakumpaa. Toisesta käynnistä alkaen metsänhenki kysyy ensin, haluaisitko muuttaa elämässäsi vielä jotain muuta: kyllä – sama keskustelu; ei juuri nyt – muistutus saavuttaa jo asetetut tavoitteet. Metsänhenki tulee esiin kerran päivässä: kun toive on tallennettu (tai ”Ei juuri nyt” -vastauksen jälkeen), se lepää huomiseen asti. Kysymykset seuraavat tunnettua tapaa muuttaa toive suunnitelmaksi: toive, lopputulos, este ja suunnitelma.",
    faq_q_books_home_chip: "Näkyykö kirjani ja sivu aloitusnäytöllä?",
    faq_q_new_me_week_challenge: "Mikä on viikon haaste?",
