    room_drawer_aria: "Pieni kaappi",
    nm_me_choose: "Valitse",
    nm_me_on_screen: "Näytöllä",
    faq_a_new_me_game: "New Me -ohjelmassa pelipainikkeet pysyvät aina samassa paikassa – käytävällä, salaisessa huoneessa ja kaikkialla metsässä; vain keskellä oleva maalaus vaihtuu. Ylhäällä: päivä matkalla, avaimet, putki ja päivän energia (kuinka paljon ohjelmasta on syöty), ja sen alla seuraava tehtävä – seuraava ateria kellonaikoineen (napautus avaa sen, ja siinä on ✓ Söin sen). Sivulla: koko päivä, haasteet ja matkani, ja niiden vieressä viikon haaste – sen 7 päivää ja ✓ tälle päivälle. Alhaalla: taikareppu (koko New Me – maailmankartta, matkani, ostoslista, saavutukset, haastepäiväkirja, kehon mitat, edistymiskuvat, kuukausikalenteri, päivätaulukko, muistutukset, ruokalista-PDF ja asetukset; se avautuu omana näkymänään). Maailmankartta, joka on repussa ensimmäisenä, näyttää kaikki metsän paikat – napauta paikkaa mennäksesi sinne; lukitussa paikassa näkyy, montako avainta se tarvitsee. Sky on hahmosi metsäpolulla: aluksi hän on Sky 1, muutaman haasteen jälkeen (4 avainta) hänestä kasvaa Sky 2 ja loppua kohden (9 avainta) Sky 3 – ja muodonmuutoksen voi nähdä. Napauta hahmoa Sky nähdäksesi kaikki vaiheet – jokaisen jo saavutetun vaiheen voi valita uudelleen, joten myös aiempi voi palata. Sky leijuu – häntä vedetään sormella tai hiirellä, ja sisäänkäynti, johon hän koskee, avautuu (lukitussa näkyy, montako avainta puuttuu). Sky tulee mukaan myös jokaiseen huoneeseen ja paikkaan ja leijuu siellä, mihin hänet jätät: vedä hänet minne tahansa, ja vedä hänen allaan olevaa hehkuvaa rengasta kääntääksesi hänet kokonaan ympäri; hän katsoo siihen suuntaan, johon hän liikkuu (tietokoneella: nuolet liikuttavat häntä, Q ja E kääntävät häntä). Käytävällä yläpalkin alla oleva pieni 🏠 palaa takaisin aloitusnäyttöön; jokaisessa huoneessa ja paikassa samassa kulmassa oleva painike palaa takaisin käytävälle.",
    faq_q_new_me_game: "Miten pelipainikkeet, maailmankartta ja Sky toimivat?",
