    room_magic_song_rec2: "Kuun harppu",
    room_magic_song_rec3: "Vesiputouksen kellopeli",
    faq_a_new_me_menu_build: "Ensin kysely kysyy, mitä aterioita syöt ja milloin (2 ateriaa + välipala, 2 ateriaa + kevyt illallinen tai molemmat), ja onko illalla jotain – syötävää tai juotavaa, mitä ja mihin aikaan. Vaihtoehdossa ”2 ateriaa + välipala” ateriat ovat lounas (11:30) ja illallinen (19:00), ja välipala on klo 16:00. Sitten näkyvät kaikki näiden aterioiden vaihtoehdot. Valitse jokaiselle aterialle enintään 2 suosikkia – ruokalistassa lukee ”tämä tai tuo”. Joissakin vaihtoehdoissa (pita ja levite, maissihiutaleet ja maito, jotain kevyttä) valitset enintään 3 asiaa, joista pidät, kunkin omana annoksenaan, ja ruokalistassa lukee ”tämä tai tuo tai tuo”; kalorit määräytyvät valintojesi mukaan. Kahvi ja juomat toimivat samalla tavalla. Jokainen valinta tasapainotetaan, joten päivä on tasan 1 300 tai 1 500. Muuta milloin tahansa: ⚙️ Asetukset → 🍽️ Kokoa ruokalistasi, tai ”Valitse enintään 3, joista pidät” aterian kortissa.",
