    nm_picks_label: "Valitse enintään 3, joista pidät",
    faq_a_myday_water_toggle: "Kyllä. Päiväni-näkymän vesilasi (+-painikkeella yksi lasi lisää) näkyy oletuksena. Piilota se kytkemällä pois ”Näytä vesi Päiväni-näkymässä” kohdassa Asetukset > Mukauttaminen ja kalenteri. Mitään ei poisteta – Vedenjuonnin Seuranta toimii edelleen, ja kun kytkin laitetaan takaisin päälle, lasi palaa.",
    faq_q_myday_water_toggle: "Voinko piilottaa veden Päiväni-näkymästä?",
    myday_water_toggle_label: "Näytä vesi Päiväni-näkymässä",
    faq_a_routine_newme_sync: "New Me -ohjelman kanssa Rutiinini-näkymän ⚙️-valikossa on kytkin ”Synkronoi New Me -ohjelman kanssa”. Kun se on päällä (oletus), päivän New Me -ateriat näkyvät Päiväni- ja Rutiinini-näkymissä – piilotettujen rutiiniaterioiden tilalla. Kun se on pois päältä, New Me -ateriat poistuvat molemmista ja rutiini on täsmälleen ennallaan. Mitään ei poisteta – kun kytkin laitetaan uudelleen päälle, kaikki palaa ja sovellus kysyy, mitkä rutiinin ateriat piilotetaan.",
