    theme_name_watercolor_wash: "Vesiväri",
    faq_a_food_list_languages: "Sisäänrakennettu ruokalista sai alkunsa israelilaisista ruoista ja niiden hepreankielisistä nimistä. Kaikilla muilla kielillä jokainen ruoka näkyy englanninkielisellä nimellään, ja haku löytää minkä tahansa tuntemansa englanninkielisen nimen (esimerkiksi 'broth' löytää Clear soupin); ruokia, joilla on vain hepreankielinen nimi, ei näytetä siellä. Kaiken, mitä listalla ei ole, voi kirjoittaa omin sanoin – tekoälyn arvio toimii kaikilla kielillä.",
    faq_q_food_list_languages: "Miksi ruokalista näyttää kielelläni englanninkielisiä nimiä ja vähemmän ruokia?",
    settings_copyright_line: "© 2026 kaikki oikeudet pidätetään. sovelluksen on kehittänyt eden zabari.",
    workout_ready_replace_btn: "Korvaa",
    faq_a_sport_workout_ai: "Kohdassa Omat treenit → ⋯ → Ohjelma tekoälyllä (ja kun taulukko on tyhjä, myös valmiiden ohjelmien vieressä olevassa ruudussa). Vastaa muutamalla napautuksella – kuinka monta kertaa viikossa, milloin, paikka, taso ja tavoite, lähes kaikissa on myös \"Muu\" – ja lisää halutessasi vapaa rivi, kuten herkkä polvi tai 5 km juoksu kesään mennessä. Tekoäly kokoaa koko viikon: treenilajit, päivät, ajat, keston, tehon, liikkeet ja lepopäivät. Ennen kuin mitään tallennetaan, näet esikatselun: \"Taulukkooni\" (taulukon tilalle tai sen lisäksi), \"Toinen ehdotus\" (enintään 3 kertaa) tai \"Muuta vastauksia\". Ohjelma on tarkoituksella maltillinen, ja jos mainitset kivun tai vamman, saat kevyitä vaihtoehtoja ja neuvon kysyä ammattilaiselta. Se käyttää samaa tekoälykiintiötä kuin aikataulu ja rutiini: 5 kertaa ilmaiseksi ja 60 kertaa kuukaudessa Premiumilla.",
