    faq_a_sport_workout_jar: "Jokaisella treenilajilla on oma värillinen tähtensä – juoksulla pinkki, kävelyllä vihreä, uinnilla sininen ja niin edelleen. Jokainen tällä viikolla kirjattu treeni, ohjelmasta tai erikseen, pudottaa tähtensä Omat treenit -kohdan ylälaidan purkkiin, ja purkki täyttyy kohti viikkotavoitettasi (napauta sitä vaihtaaksesi tavoitteen). Kun tavoite täyttyy, purkki hehkuu. Vieressä oleva pieni purkki laskee, monenako viikkona peräkkäin täytit sen.",
    faq_q_sport_workout_jar: "Mitä ovat Omat treenit -kohdan värilliset tähdet ja purkki?",
    faq_a_sport_workout_gcal: "Kyllä – kohdassa ⋯ → Google-kalenteri (kun Google-kalenteri on yhdistetty Asetuksissa). Jokaisesta treenistä, jolla on aika, tulee tapahtuma, joka toistuu viikoittain sen päivinä, ja sovelluksen muutokset päivittävät sen. Muistutukset tulevat vain sovelluksesta, joten Google ei lisää omiaan, eivätkä treenit koskaan näy sovelluksessa kahdesti. Uusi napautus poistaa Google-kalenterista vain treenit.",
    faq_q_sport_workout_gcal: "Voivatko treenini näkyä Google-kalenterissa?",
    workout_gcal_btn: "Google-kalenteri",
    workout_gcal_error: "Google-kalenteria ei voitu päivittää – seuraavan muutoksen yhteydessä yritetään uudelleen",
    workout_gcal_not_connected: "Yhdistä Google-kalenteri ensin Asetuksissa",
    workout_gcal_off_toast: "Treenit poistettiin Google-kalenterista",
    workout_gcal_on_toast: "Treenisi ovat Google-kalenterissa",
    faq_a_sport_workout_reminder: "Kyllä – treenissä Muistutus: 10 minuuttia, 30 minuuttia tai tunti ennen, tai oma aika (treenillä pitää olla aika). Se soi kuten muut muistutuksesi, kerran ja yhdessä paikassa: sovelluksessa, jos se on auki, muuten puhelimessa. \"Valmis\" kirjaa treenin historiaan, ja \"Ei vielä\" muistuttaa uudelleen 5 minuutin päästä.",
    faq_q_sport_workout_reminder: "Voinko saada muistutuksen ennen treeniä?",
    workout_reminder_30min: "30 minuuttia ennen",
    workout_reminder_label: "Muistutus",
    workout_reminder_need_time: "Lisää aika saadaksesi muistutuksen",
    faq_a_sport_workout_share: "Kohdassa ⋯ → Jaa viikosta tulee lasimainen kuva teemasi väreissä, ja mukana on huomaamaton linkki sovellukseen (puhelimessa se menee suoraan jakovalikkoon, tietokoneella kuva tallentuu). ⋯ → Tulostettava PDF avaa siistin sivun koko viikosta, ja jokaisen treenin ja liikkeen vieressä on ruutu rastia varten – valitse \"Tallenna PDF-muodossa\" tai tulosta. Ohjelma näkyy myös Asetusten tietoraportissa, urheiluosiossa.",
    faq_q_sport_workout_share: "Miten jaan tai tulostan treeniviikkoni?",
    share_image_saved: "Kuva on tallennettu – voit liittää sen",
    share_save_image: "Tallenna kuva",
    workout_pdf_btn: "Tulostettava PDF",
    workout_share_btn: "Jaa",
    faq_a_sport_workout_board: "Kohdassa ⋯ → Viikkotaulu jokainen päivä on sarake: vedä treeni toiselle päivälle (puhelimessa paina ensin pitkään). Treenissä \"Myös Rutiinissani\" lisää sen rutiiniisi sen ajalle ja päiville, ja muutokset pysyvät samana molempiin suuntiin; Rutiinini kohdasta \"Lisää omiin treeneihin\" tekee päinvastoin. ✓ toisessa paikassa lasketaan molempiin, ja Päiväni-näkymässä se näkyy vain kerran – veden vieressä olevassa merkissä.",
    faq_q_sport_workout_board: "Miten siirrän treenin toiselle päivälle ja yhdistän sen Rutiiniini?",
    routine_in_workouts_btn: "Avaa omissa treeneissä",
    routine_to_workout_btn: "Lisää omiin treeneihin",
    routine_to_workout_done: "Lisätty omiin treeneihin 💪",
