    workout_moved: "Siirretty: {day}",
    workout_routine_need_time: "Lisää aika, jotta sen voi laittaa Rutiiniini",
    workout_routine_toggle: "Myös Rutiinissani",
    workout_view_board: "Viikkotaulu",
    workout_view_timeline: "Aikajana",
    faq_a_sport_workout_plan: "Treenien Seurannassa, kohdassa \"Omat treenit\": + Treeni – laji, päivät, aika, kesto, teho ja paikka (myös \"Muu\"). Voima-, toiminnallisiin ja uintitreeneihin voi lisätä liikelistan, ja Lepo merkitsee lepopäivän. Voit myös aloittaa valmiista ohjelmasta. Päivän treeni näkyy isona ja koko viikko sen alla; ✓ kirjaa sen treenihistoriaan tehon kanssa. Kohdassa ⋯ asetetaan viikkotavoite (treenit tai minuutit) – jokainen tehty treeni pudottaa tähtensä purkkiin.",
    faq_a_sport_workout_today: "Päiväni-näkymässä veden vieressä pieni merkki näyttää päivän treenin – napautus avaa tiedot, ✓:n ja ▶:n. ▶ käynnistää ajastimen, joka jatkaa kulkuaan aloitusnäytön merkissä, ja \"Lopeta\" kirjaa treenin todellisella ajalla. Jos New Me -haaste \"Kaksi viikkoa liikettä\" on käynnissä, kirjattu treeni lasketaan siihen itsestään.",
