    faq_a_new_me_magic_themes: "Viisi kimaltelevaa teemaa, jotka kuuluvat New Me -ohjelmaan: Lumottu metsä, Tähtipöly, Ruusukeiju, Taianomainen revontuli ja Kultainen hämärä. Valitse yksi New Me -ohjelmassa (⚙️ Asetukset > Värit) tai kohdassa Asetukset > Ulkoasu ja näyttö, niin kimaltava sivellin maalaa näytön sillä teemalla. Taikateema tuo kimalletta koko sovellukseen ja jokaiseen napautukseen. Voit palata mihin tahansa muuhun teemaan milloin vain.",
