    apptour_focus_text: "Kaikki väistyy paitsi se yksi asia juuri nyt – ison ✓:n kera. Sen jälkeen tulee seuraava.",
    apptour_m_presets_text: "Tallennetut ateriasi yhdessä paikassa: haku, viimeksi käytetyt, vuorokaudenajan mukaan – ja ＋ lisää aterian tälle päivälle.",
    apptour_night_text: "🌙 tummentaa koko sovelluksen, ☀️ tuo päivän takaisin.",
    apptour_noteline_text: "Kirjoita ja napauta ➤ – se tallentuu muistiinpanoihisi. Alun 📝 vaihtaa 🛒 ostoksiin tai 🍎 tallennettuun ateriaan.",
    apptour_search_text: "Muistiinpanot, ostokset, kalenteri, reseptit, vihot, tavoitteet, taulukot ja kirjat – yksi haku löytää kaiken.",
    faq_a_new_me_ai_menu: "Ennen ruokalistaa kysely kysyy, mitä aterioita syöt ja milloin (2 ateriaa + välipala, 2 ateriaa + kevyt illallinen tai molemmat), syötkö illalla jotain pientä ja mihin aikaan, mitä et syö ja miten juot kahvia tai teetä. Sitten tekoäly tekee jokaiselle aterialle 3 vaihtoehtoa – kukin aterian osuuden kokoinen päivästä, joten päivä on edelleen tasan 1 300 tai 1 500 – sekä juomaideoita, jotka tallentuvat vakiojuomiksesi. Valitse kullekin aterialle enintään 2 suosikkia; alkuperäisen ruokalistan vaihtoehdot ovat suoraan niiden alla, ja kohdassa 🔄 Vaihda ne tulevat oman ruokalistasi jälkeen. 🔄 Muita vaihtoehtoja tekee uuden sarjan (3 kertaa kyselyä kohden). Vastausten muuttaminen tai uusi ruokalista milloin tahansa: ⚙️ Asetukset → ✨ Oma ruokalista (AI).",
    faq_q_new_me_ai_menu: "Miten New Me:n oma ruokalista toimii?",
