    nm_ai_menu_drinks: "Juomia sinulle",
    nm_ai_menu_error: "Omaa ruokalistaa ei nyt saatu tehtyä – tässä alkuperäinen ruokalista. Voit yrittää uudelleen, tai myöhemmin kohdasta ⚙️ Asetukset.",
