    nm_ai_offer_text: "Vastaa muutamaan lyhyeen kysymykseen – milloin syöt, mitä et syö ja miten juot kahvisi – niin tekoäly tekee sinulle sopivan ruokalistan. Alkuperäinen ruokalista jää myös.",
