    apptour_s_menu_text: "Kaikki, mitä voit säätää, on täällä viidessä ryhmässä. Avataan ne 👇",
    apptour_skip_part: "Ohita tämä osa",
    apptour_start: "Aloita kierros",
    nm_sales_premium: "Sisältää koko Premiumin",
    nm_unlock_premium: "Myös koko Premium on nyt avattu.",
    settings_sub_status_newme: "Premium sisältyy New Me -tilaukseesi.",
    room_back_to_shelf: "Hyllylle",
    faq_a_new_me_day_total: "Jokainen päivä tulee tasan suunnitelman mukaan: ateriat, noin 150 kaloria kahviin ja juomiin päivän mittaan sekä se, mitä on valittu illaksi – jotain pientä syötävää tai jotain juotavaa. Illaksi valitse enintään 3, joista pidät (esimerkiksi banaani, jogurtti tai 2 palaa tummaa suklaata; tai yrttitee, tee ja tilkka maitoa tai lämmin maito), ja niiden kalorit otetaan aterioista. Jokainen valinta tasapainottuu itsestään: pienempi tai isompi vaihtoehto, pois jätetty ateria, pieni aamiainen ja sen mukana tuleva pieni ateria tai ilta – erotus lisätään aterioihin tai vähennetään niistä, kuhunkin sen koon mukaan, ja jokaisen aterian alla lukee, kuinka paljon (+ tai −) ja mitä voi lisätä tai jättää pois. Jo merkitty ateria pysyy sellaisena kuin se kirjattiin. Kyselyssä jokaisen aterian kohdalla näkyy sen korjaus, ja pieni laatikko näyttää ateriat, juomat, illan ja kokonaismäärän. Tekeekö sinä päivänä mieli jotain muuta? Pidä kokonaismäärä samoissa kaloreissa tai alle.",
    faq_q_new_me_day_total: "Miten New Me -päivä tulee tasan 1 300 / 1 500:aan, ja missä juomat lasketaan?",
