    books_quotes_chip: "Lainaukset",
    faq_a_book_quotes: "Salaisen huoneen hyllyyn (Lainaukset) tai Lukunurkkauksen pienen 💬 Lainaukset -merkin kautta – lista on sama. Napauta ”+ Lainaus”, kirjoita lause ja valitse kirja Lukunurkkauksesta tai kirjoita toinen nimi kohdasta ”✏️ Muu”; kirjoittaja on valinnainen. ✏️ muokkaa lainausta ja 🗑️ poistaa sen. Lainaukset ovat kirjanmerkkejä, joita pyyhkäistään – yläreunan 🎨 vaihtaa kuviin tai korttiseinään.",
    faq_a_room_wish_jar: "Salaisen huoneen hyllyllä on lasipurkki unelmille. Napauta pientä purkkia ylimmällä hyllyllä (tai Hylly > Toivepurkki) ja kirjoita, millaisen haluaisit elämäsi olevan – niin hurjasti kuin haluat, ilman oikeaa tai väärää. Jokainen toive taittuu lapuksi, joka putoaa purkkiin. ”Nosta lappu” avaa satunnaisen lapun, ja jokaisen lapun voi myös avata erikseen. Kun avaat saman toiveen toisen kerran, voit tehdä siitä tavoitteen ja jakaa sen pieniin askeliin. Kerran viikossa lempeästi ilmestyy lappu, jossa on yksi toiveistasi – ilman painetta, vain muistutuksena siitä, mihin olet matkalla.",
