    faq_a_saved_meals_page: "Tallennetuilla aterioilla on oma sivunsa: Ravinto ja Mittarit > ⭐ Tallennetut ateriat (tai ⭐ valikossa). Yläreunan haku löytää aterian nimen tai raaka-aineen perusteella, ”Äskettäin käytetyt” näyttää, mitä olet lisännyt viime aikoina, ja välilehdet (Aamiainen, Lounas, Päivällinen, Keitot…) näyttävät jokaisen vuorokaudenajan. ”+ Tänään” lisää aterian tämän päivän Päivittäiseen Ateriaseurantaan seuraavaan vapaaseen kohtaan. Napauta ateriaa muokataksesi tai poistaaksesi sen, ja yläreunan ＋ lisää uuden.",
