    presets_tab_sweet: "Makeiset",
    faq_a_notes_sticky_look: "Muistiinpanot ovat lyhyt lista lasikortteja – 🎨 Muistiinpanojen yläreunassa vaihtaa koko Muistiinpanojen ulkoasun: listan, yläreunan päiväpainikkeet ja ikkunan, jossa muistiinpano kirjoitetaan – lasi, selkeä lista, arkistokortit tai washi-teippi. Raahattava muistiinpano säilyttää täsmälleen oman ulkoasunsa ja värinsä. Napauta muistiinpanon tekstiä avataksesi sen – siellä voit muokata sitä, vaihtaa värejä ja nähdä, milloin se on viimeksi kirjoitettu. Napauta ○, kun asia on hoidettu, ja × siirtää sen arkistoon (listan alareunan 🗑️ tuo sen takaisin). Vedä sitä ⠿-kahvasta muuttaaksesi järjestystä, siirtääksesi sen ”Myöhemmin”-kohdan alle tai ylhäällä olevalle päivälle. ! merkitsee muistiinpanon kiireelliseksi – se liukuu pehmeästi ylimmille riveille pienen ”Kiireellinen”-tunnisteen kera; uusi napautus poistaa merkinnän.",
    faq_q_notes_sticky_look: "Miten avaan, muokkaan tai poistan muistiinpanon?",
    note_to_archive_btn: "Siirrä arkistoon",
    faq_a_routine_clash: "Jos siihen aikaan samoina päivinä on jo jotain, saat kaksi vaihtoehtoa: ”Korvaa” – uusi saa sen ajan, ja valitset toisen ajan sille, joka siinä oli (kun muokkaat olemassa olevaa, sen aiempaa aikaa ehdotetaan, joten ne vain vaihtavat paikkaa), tai ”Molemmat” – molemmat jäävät samaan aikaan, toinen toisen alle. Jos päivät ovat eri (esimerkiksi toinen su–to ja toinen perjantaina), mitään ei kysytä.",
    faq_q_routine_clash: "Mitä tapahtuu, jos laitan rutiiniin jotain jo varattuun aikaan?",
