    routine_clash_title: "Klo {time} on jo: {title}",
    faq_a_new_me_coffee: "Tämän päivän ruokalistan alla on lyhyt yhteenveto: montako kaloria kaikki päivän ateriat ovat yhteensä, paljonko on jäljellä kahviin ja juomiin, sekä painikkeet valituille kahveille ja juomille – yksi napautus lisää sen kohtaan Juomat. Painikkeiden alla olevassa kohdassa ”Valitse enintään 3, joista pidät” (ja kyselyssä) valitset, mitä näkyy: vesi / hiilihapotettu vesi, yrttitee, light-limsa, musta / americano (~5), tee ja tilkka maitoa (~25), veteen tehty kahvi ja enintään 100 ml maitoa tai kasvijuomaa (~50), kevyt kaakao, lämmin maito tai tavallinen kahvi / latte (~120).",
