    faq_a_recipe_examples: "Omien reseptiesi alla on esimerkkireseptejä: aamiaisia, salaatteja, keittoja, pääruokia, lisukkeita, välipaloja, jälkiruokia ja vegaanisia ruokia, jokaisessa valmistusaika, kalorit annosta kohden ja montako grammaa yksi annos painaa. Avaa resepti napauttamalla sitä; ”Tallenna Omiin Resepteihin” tekee oman kopion, jota voit muokata. Luokkatunnisteet suodattavat, ja saman tunnisteen napauttaminen uudelleen näyttää taas kaiken.",
    faq_a_recipe_grams: "Reseptissä kalorien vieressä lukee ”1 annos ≈ X g”. Omissa resepteissäsi täytä reseptilomakkeeseen ”Grammaa per annos” (ja halutessasi valmistusaika): molemmat ovat vapaaehtoisia, ja aika näkyy reseptin värinauhassa.",
