    recipes_examples_title: "Esimerkkireseptit",
    faq_a_recipe_scan_multi: "Kyllä. Napauta kohdassa ”Lisää Resepti” 📷 ja valitse yksi kuva tai useampi (enintään 6; myös PDF käy). Jokainen näkyy lyhyessä listassa, jossa valitset, mitä siinä on: Kaikki, Ainekset tai Valmistus, ja ”➕ Vielä yksi kuva” lisää uusia. Napauta sitten ”✨ Skannaa resepti”: tekoäly kokoaa kaiken yhdeksi reseptiksi, oikeassa järjestyksessä ja ilman toistuvia rivejä, ja se lasketaan yhdeksi skannaukseksi. Myös useat kuvat, jotka valitset tekoälyavustajan kohdasta 📷 Kuva, avautuvat tähän.",
