    faq_a_note_written_at: "Avaa muistiinpano napauttamalla sen tekstiä. Sisällä, tekstin alla, näkyy milloin se on viimeksi kirjoitettu, tarkalla päivämäärällä ja kellonajalla. Vain itse tekstin muuttaminen päivittää sen: arkistointi ja palautus, ✓-merkintä, värit tai muistiinpanon siirtäminen eivät muuta sitä.",
    faq_q_note_written_at: "Miten näen, milloin kirjoitin muistiinpanon?",
    note_written_at: "Viimeksi kirjoitettu: {date}",
    faq_a_new_me_month: "Taikarepussa → Kuukausikalenteri: jokainen päivä on väritetty sen mukaan, montako ateriaa merkittiin, ‹ ›-nuolilla vaihdetaan kuukautta, ja kalenterin alla näkyy kuukauden päivittäinen kalorikeskiarvo. Päivää napauttamalla näet, montako ateriaa merkittiin ja montako kaloria syötiin sinä päivänä.",
    faq_q_new_me_month: "Mistä näen New Me -ohjelmassa kuukauden taaksepäin ja keskimääräiset kalorit?",
