    nm_month_day_line: "Merkityt ateriat: {checks} · kalorit: {kcal}",
    nm_extra_line_small: "{n} kaloria tälle aterialle pienestä aamiaisesta – esimerkiksi {ideas}",
    faq_a_new_me_small_breakfast: "Kevyt aamiainen (noin 170 kcal): speltti-pita (enintään 100 kcal) ja levite tai juusto sekä vihannes – valitse enintään 3, joista pidät, esimerkiksi 1 teelusikallinen suklaalevitettä, 1 teelusikallinen maapähkinävoita tai viipale juustoa (rasvaa enintään 22 %). Koska se on pieni, sen kanssa tulee toiseen aikaan ”Lisäksi pieni ateria” (puolitoista tuntia myöhemmin, esimerkiksi 11:30 → 13:00 – minkä tahansa muun ajan voi valita): toinen pita ja levite, proteiinijogurtti ja hedelmä, riisikakut ja rahka, murot ja maito tai puolikas pita ja kananmunat – enintään noin 200 kcal, omalla ✓-merkillään. Mitä vielä jää yli, jaetaan muille aterioille, ja jokainen ateria näyttää, paljonko se sai lisää, joten päivän summa pysyy suunnitelman mukaisena. Valitse se kyselyssä tai vaihda siihen vain tälle päivälle 🔄-painikkeella – esimerkiksi kun aamiainen myöhästyy.",
