    faq_a_ai_icon: "Voit – kohdassa Asetukset > Ulkoasu ja näyttö. Oletuksena on pehmeä kupla, ja Premiumilla voit valita myös leijuvan aivon tai robotin.",
    faq_a_new_me_favorites: "Voit. Kyselyssä (ja kun teet sen uudelleen asetuksista) voit valita jokaiselle aterialle enintään 2 vaihtoehtoa. Ensimmäinen näkyy ruokalistassa, ja sen alla on toisen vaihtoehdon ”tai”-rivi – sitä napauttamalla vaihdat siihen vain tälle päivälle. Ja jos aamiaista ei ehditty syödä ajallaan, ”⏰ Myöhemmin” siirtää sen myöhemmäksi päivään muuttamatta kaloreita.",
    faq_a_theme_mode: "Jotkin erikoisteemat näyttävät kauneimmilta tummina – Vesiväri, Revontulet, Barbie ja kaksi kimalleteemaa –, joten jonkin niistä valitseminen vaihtaa sovelluksen tummaan tilaan, ja minkä tahansa muun teeman (myös raketin) valitseminen vaaleaan. Musta ja Tummanharmaa pysyvät tummina. Voit aina vaihtaa jälkikäteen valikon 🌙-painikkeella tai asetusten Vaalea Tila -kohdasta.",
    faq_a_water_month: "Veden seurannasta. Jokaisessa tämän päivän lokin merkinnässä näkyy kellonaika, jolloin se lisättiin, ja ”Kuukausitaulukko” avaa koko kuukauden: jokaisessa päivässä näkyy, montako litraa juotiin (✓, kun päivän tavoite saavutettiin), ja päivää napauttamalla näet sen merkinnät kellonaikoineen.",
