    dev_sim_panel_title: "PM – vain sinulle",
    faq_a_new_me_weight_optional: "Ei. Kyselyn nykyinen paino ja tavoitepaino ovat molemmat valinnaisia. Jos punnitus lisätään myöhemmin (⚖️ Paino New Me -ohjelman ”Matkani”-osiossa tai painoseurannassa), edistyminen lasketaan ensimmäisestä.",
