    nm_unlock_desc: "Ruokalista, haasteet ja matka ovat valmiina – askel kerrallaan, yhdessä.",
    nm_unlock_title: "New Me on avattu!",
    room_reveal_star: "Katon kaukoputkeen syttyi uusi tähti ✨",
    faq_a_room_records: "Levysoitin on huoneessa alusta asti, nojatuolin vieressä olevalla puunkannolla. Sen levyt avaavat YouTubessa viime vuosien isojen hittien viralliset musiikkivideot, ja niiden alla on viisi rauhallista sävelmää, jotka soivat täällä huoneessa – levy pyörii niiden soidessa, ja ”⏹ Pysäytä” lopettaa musiikin.",
    faq_a_room_roof_gifts: "Ne tulevat 8. avaimen myötä. Kaukoputken napautus antaa katsoa sen läpi: yötaivas aivan läheltä – vedä (tai käytä nuolia) katsoaksesi ympärillesi – ja päättyneet haasteesi muodostavat siinä tähtikuvion, yksi tähti jokaista haastetta kohden; tähden napautus näyttää, mikä haaste se oli. Pienen arkun napautus avaa sen – toistaiseksi se on tyhjä – ja uusi napautus sulkee sen.",
