    ai_chat_food_updated: "Päivitetty:",
    faq_a_ai_chat_food_fix: "Voi. Napauta keskustelussa vastauksen alla ✏️ Korjaa kalorit / proteiini, muuta lukuja ja napauta Tallenna. Vain juuri lisätty osa muuttuu – vaikka se olisi liitetty jo olemassa olleeseen välipalaan. Tekoäly voi erehtyä, joten nopea tarkistus kannattaa.",
    faq_a_new_me_home_btn: "Jos sinulla on New Me, pieni 💎 keskittymistilan vieressä aloitusnäytön yläreunassa avaa tämän päivän ruokalistan. Tämän päivän ateriat näkyvät myös Päiväni-näkymässä, jokaisella oma ✓.",
    faq_a_routine_item_days: "Voi. Napauta kohtaa Rutiinini-näkymässä ja valitse sen päivät kohdasta 📅 Päivät – esimerkiksi vain maanantaista perjantaihin. Muina päivinä se ei näy Päiväni-näkymässä eikä siinä ole ✓:aa; Rutiinini-näkymässä se pysyy, haaleampana, päivät vieressään. Kortti, joka kysyy kohdasta 3 päivän ilman ✓:aa jälkeen, laskee vain kohdan omat päivät.",
    faq_q_ai_chat_food_fix: "Voiko kaloreita tai proteiinia korjata, kun avustaja on kirjannut ruoan?",
    faq_q_new_me_home_btn: "Missä New Me on aloitusnäytöllä?",
    faq_q_routine_item_days: "Voiko yksi Rutiinini-kohta olla vain tiettyinä päivinä?",
    routine_item_days_label: "📅 Päivät",
    home_note_meal_ph: "Etsi tallennettu ateria…",
    menu_quick_search: "Pikahaku",
    nm_times_hint: "Vinkki: voit asettaa myöhäisimmän ajan, jolloin yleensä syöt kunkin aterian – esimerkiksi 9:00, jos syöt usein kahdeksan aikaan.",
    room_game_marquee: "Matkalla – pysähdy nauttimaan",
    room_sand_erase_aria: "Hankaa pyyhkiäksesi kirjoituksen",
    faq_a_home_note_line: "Kirjoita aloitusnäytön keskellä olevalle riville ja napauta ➤ (tai Enter) – se tallentuu Muistiinpanoihin. Napauta rivin alussa olevaa 📝:ää, niin siitä tulee 🛒: silloin kirjoittamasi menee Ostoslistalle. Napauta vielä kerran, niin saat 🍎: kirjoita muutama kirjain, sopivat tallennetut ateriat tulevat näkyviin, ja yksi napautus kirjaa aterian päivän aterioihin. 🎤:llä voit vain sanoa sen ääneen.",
    faq_a_night_mode: "Avaa valikko ☰ ja napauta ylhäällä 🌙 – koko sovellus tummuu. Samassa kohdassa oleva ☀️ tuo päivän takaisin. Sama löytyy myös Asetuksista, kohdasta Vaalea Tila.",
    faq_q_home_note_line: "Miten kirjoitan pikamuistiinpanon aloitusnäytöltä?",
    faq_q_night_mode: "Miten vaihdan yötilaan?",
    menu_day_mode: "Päivätila",
    menu_night_mode: "Yötila",
    faq_a_secret_room_yoga: "Metsäpolun päässä on hehkuva portti, ja sen takana, vesiputouksen vieressä, metsän olennot – Lumi, Puffi, Nixie ja Sparklet – istuvat matoillaan puoliympyrässä, ja Flora, joogaopettaja, istuu niitä vastapäätä kiven päällä olevalla ainoalla matolla. Napauta Floraa: hän avaa silmänsä, kaikki tulee lähemmäs, ja keskustelu alkaa hitaasti, lukemiseen jää aikaa – Flora kysyy, mitä kaikille kuuluu, jokainen olento vastaa omalla nimellään (jokaisen rivin vieressä on pieni kuva puhujasta), ja sitten hän kysyy sinulta, miltä tuntuu läheisten ihmisten kanssa. Keskustelu jatkuu vastaustesi mukaan – hyvät ihmiset, joku, jonka kanssa on vaikeaa, tai vähän yksinäinen olo. Jokainen polku päättyy pieneen tehtävään (sen voi lisätä suoraan Päiväni-näkymään; kun tehtävänä on kirjoittaa jotain, kirjoittamiselle on paikka, ja teksti tallentuu taikapäiväkirjaan) ja asentoon, jossa hengitetään kolme kertaa yhdessä. ↩ palaa askeleen taaksepäin ja ✦ aloittaa uuden keskustelun. Seuraava avain avaa vesiputouksen: kun istut kivelle, kaikki katoaa ja jäljelle jää vain veden ääni. Kun kumarrut lammen ylle, vedestä nousee kysymys – mitä todellinen itsesi tekisi tänään? – ja vastauksesta tulee pieni tehtävä Päiväni-näkymään. Se on lempeä hetki eikä korvaa keskustelua ammattilaisen kanssa.",
    faq_q_secret_room_yoga: "Mitä metsäjoogassa tapahtuu?",
