    yg_g_hard: "Kiitos, että sanoit sen. Mikä painaa eniten?",
    yg_g_listen: "On väsyttävää, kun ei tule kuulluksi. Äänesi on tärkeä, hiljaisenakin.",
    yg_g_new: "Uudet ihmiset alkavat pienestä moikasta. Kurssi, kävely, ryhmä – yksi askel.",
