    nm_time_hour: "Tunti",
    nm_time_minutes: "Minuutit",
    routine_time_taken: "Tähän aikaan on jo jotain: {title}",
    faq_a_new_me_times: "Alun kyselyssä ja milloin tahansa New Me -ohjelman asetuksissa → ”Ruoka-ajat”. Jos rutiinissasi on jo ruoka-ajat, ne otetaan sieltä – ja rutiinin ateriat voi piilottaa, jolloin niiden tilalla näkyvät New Me -ateriat. Jos ei, valitset montako ateriaa päivässä (2 ateriaa + välipala / 2 ateriaa + kevyt illallinen / 2 ateriaa + välipala + kevyt illallinen) ja milloin kukin on. Vaihtoehdossa ”2 ateriaa + välipala” ne ovat lounas klo 11:30, välipala klo 16:00 ja illallinen klo 19:00 (minkä tahansa voi muuttaa). Nämä ovat ruoka-aikasi kaikkialla: käytävällä, Päiväni-näkymässä, Rutiinini-näkymässä ja muistutuksissa. Valitsitpa mitä tahansa, päivän kalorit pysyvät samoina – pois jäävä jaetaan muille aterioille.",
    faq_q_new_me_times: "Miten asetan ruoka-aikani New Me:ssä?",
    nm_times_count: "Montako ateriaa päivässä?",
    nm_times_from_routine: "Kyllä, ota ne rutiinistani",
    nm_times_hide: "Piilota rutiinini ateriat ja näytä niiden tilalla New Me -ateriat",
    nm_times_later: "Myöhemmin",
    nm_times_manual: "Ei, valitse tässä",
    nm_times_none_found: "Rutiinissasi ei ole vielä aterioita – valitse tässä, montako ja milloin.",
    nm_times_q: "Onko rutiinissasi kiinteät ajat syömiselle?",
    nm_times_saved: "Ruoka-ajat tallennettu",
    nm_times_title: "Ruoka-ajat",
    faq_a_routine_exact_time: "Voi. Kun kuvailet tekoälylle rutiinin tarkalla kellonajalla (esimerkiksi \"16:10 treidaus\"), se tallentuu juuri niin – sitä ei pyöristetä tasatuntiin. Kaikki rutiiniin kirjoitettu näkyy aina taululla, vaikka sen tuntia ei olisi valittu tuntiasetuksissa, ja kun poistat tunnin, jossa on jotain, sinulta kysytään ensin. Ajan voi vaihtaa myös käsin: napauta aikaa kohteen ikkunassa ja valitse tunti ja minuutit.",
    faq_q_routine_exact_time: "Voiko rutiinissani olla tarkka kellonaika, kuten 16:10?",
    room_item_sand: "Kirjoita hiekkaan",
    room_item_yoga: "Jooga metsässä",
    room_sand_ph: "Mistä haluaisit päästää irti?",
