    routine_daysoff_which: "Mitkä päivät?",
    faq_a_secret_room_diary: "Vain sinä. Päiväkirjan sivut tallentuvat tiliisi, joten ne ovat jokaisella laitteella, eikä kukaan muu näe niitä. Salaisen huoneen kirjoituspöydällä oleva taikapäiväkirja avaa sen, ja niin avaa myös musiikkinurkkauksen päiväkirja. Uuden sivun alla on taitettu kuukausitaulukko: piste merkitsee jokaisen päivän, jolla on sivu, ja päivän napauttaminen avaa sen sivut – siellä sivun voi myös poistaa. Kun päiväkirja on jo avattu, sen voi lisätä myös päävalikkoon – päiväkirjan omalla kytkimellä tai New Me -ohjelman asetuksista.",
    faq_a_secret_room_places: "Jokainen metsäportin sisäänkäynti aukeaa omalla avaimellaan. Niiden takana: kuisti meren rannalla (pienellä pöydällä Aladdinin lamppu – napautus, ja siitä nousee metsänhenki taianomaisessa usvassa, pyörähtelee ympäriinsä ja aloittaa keskustelun toiveestasi – katso ”Mitä lampun henki tekee?”), kitara ja päiväkirja (kitara soittaa lyhyen, rauhallisen sävelmän ja vaikenee itsestään, ja puussa roikkuvat kolme levyä soittavat kukin oman taianomaisen sävelmänsä – uusi napautus pysäyttää sen – ja kannolla olevaan päiväkirjaan kirjoitetaan), hengityshuone (hiljainen järvi auringonlaskussa – vedellä kelluu lootuslyhty: napauta sitä, kirjoita toive, ja se ajelehtii sen kanssa kauas takaisin järvelle; taikasauvalla voit kirjoittaa hiekkaan sen, mistä haluat päästää irti, ja se pysyy, kunnes pyyhit sen sormella pois) ja metsäpolku (se aukeaa yöllä, ja lyhtyjen napauttaminen vaihtaa sen päiväksi; penkillä voi istua, ja kyltin napauttaminen tuo sen lähelle – taulu, jossa on kuusi pientä kysymystä rastitettavaksi). Lukitussa sisäänkäynnissä näkyy, montako avainta vielä puuttuu. Polun päässä hehkuva portti vie vesiputouksen viereiseen joogaan – ja sieltä itse vesiputoukselle.",
    faq_q_secret_room_diary: "Kuka näkee päiväkirjan?",
