    ai_chat_working_table: "Hetkinen, teen taulukkoa…",
    dev_weather_preview_label: "Esikatselu – vain omalla tililläsi:",
    faq_a_ai_chat: "Napauta kuplaa, niin keskustelu avautuu. Valitse, mitä haluat tehdä – jotain kalenteriin, mitä söit, kuva reseptistä tai uusi taulukko – tai kirjoita vain, niin avustaja ymmärtää itse. Voit myös napauttaa 🎙️ ja puhua kirjoittamisen sijaan. Kalenteria varten voit valita kerran, joka viikko tai joka päivä. Vastaus tulee keskusteluun, ja sieltä voit jatkaa johonkin muuhun tai avata kalenterin / sen, mitä söit.",
    faq_a_new_me_hall: "New Me alkaa taikametsän portilta, ja sen jokainen sisäänkäynti on oma paikkansa: jättiläispuun pyöreä ovi vie salaiseen huoneeseen, ontto tukki kuistille meren rannalla, sienitalo kitaran ja päiväkirjan luo, pieni pajukaari hengityshuoneeseen, iso pajukaari metsäpolulle, ja tikkailla varustettu kukkakaari nousee tähtikatolle, kun katto aukeaa. Lukitussa sisäänkäynnissä on lukko. Polulla leijuu hahmosi Sky, ja pelipainikkeet ovat ympärillä: seuraava tehtävä, viikon haaste, taikareppu, jossa on koko New Me, maailmankartta ja työkalut. Yläreunan avainten napautus kertoo, miten avaimia saa.",
    faq_a_new_me_routine_meals: "Kun New Me -ohjelmassa on asetettu ateriat ja Rutiinini-kohdassa on myös aterioita, New Me kysyy, piilotetaanko ne ja näytetäänkö niiden tilalla New Me -ateriat – jotta mikään ei näy kahdesti. Rutiinini näyttää sitten New Me -ateriat niiden aikoina, merkinnöillä 💎 ja ✓ (aterian nimen napautus avaa ikkunan toisen aterian valitsemiseen tai sen ajan muuttamiseen, suoraan siinä rutiinin päällä). Mitään ei poisteta: ne palaavat kohdasta New Me ⚙️ Asetukset → Ateriat rutiinissa tai kytkemällä pois ”Synkronoi New Me -ohjelman kanssa” Rutiinini-näkymän ⚙️-valikosta. Ilman aktiivista New Me -ohjelmaa ne palaavat itsestään.",
    faq_a_room_computer: "Se on pieni keskustelu, joka alkaa kysymyksellä ”Miten päiväsi on tähän mennessä mennyt?” – hyvin, kiireisesti vai raskaasti – ja jatkuu kanssasi askel kerrallaan aina pieneen tehtävään asti lopussa (joka voi mennä myös suoraan Päiväni-näkymään). Vastauksia voi napauttaa tai kirjoittaa vapaasti – kirjoitettu teksti yhdistetään lähimpään vastaukseen. ”↩ Takaisin” palaa askeleen taaksepäin, jotta voit vastata toisin, ja ”Uusi keskustelu” aloittaa alusta milloin tahansa. Kiireisen tai raskaan päivän jälkeen voit palata tietokoneen ääreen myöhemmin samana päivänä: ”Olen taas täällä...” jatkaa keskustelua. Alhaalla oleva vihreä valo sammuttaa ja käynnistää tietokoneen. Vain valinnat tallennetaan, vain tälle laitteelle ja vain päivän loppuun asti.",
    faq_q_ai_chat: "Miten puhun avustajalle?",
    faq_q_new_me_hall: "Mikä on New Me -ohjelman käytävä?",
    faq_q_new_me_routine_meals: "Miksi Rutiinini näyttää New Me -ateriat?",
    faq_q_room_computer: "Miten salaisen huoneen tietokone toimii?",
