    dictation_btn_aria: "Puhu, niin se kirjoitetaan",
    dictation_mic_denied: "Mikrofoni on estetty – salli se selaimen osoitteen vieressä olevasta 🔒-kuvakkeesta tai puhelimen asetuksista",
    faq_a_dictation: "Kyllä – napauta 🎤-mikrofonia pikamuistiinpanon tai vihon kirjoitussivun kulmassa ja puhu: sanat kirjoittuvat puhuessasi sovelluksen kielellä. Napauta uudelleen lopettaaksesi. Ensimmäisellä kerralla selain pyytää lupaa käyttää mikrofonia. Toimii Chromessa / Androidissa ja iPhonen Safarissa. Tietokoneella tarvitset mikrofonin ja selaimen, kuten Chromen, Edgen tai Safarin – jos jotain puuttuu, viesti kertoo tarkalleen mitä.",
    faq_q_dictation: "Voinko puhua kirjoittamisen sijaan?",
    faq_a_secret_room: "Huone, joka on vain sinun, New Me -ohjelman sisällä – talo jättiläispuun uumenissa. Näet yhden seinän kerrallaan ja käännyt nuolilla (tai pyyhkäisemällä). Ensimmäinen avain tulee, kun ateriaan on tullut ✓ kolmena eri päivänä, ja se avaa oven – ja sen mukana koko huoneen: tietokoneen, pelin, levysoittimen, hyllyn, jonka sisällä on kirjasto, ja kissan. Sen jälkeen jokainen päättynyt haaste (myös viikon haaste) antaa avaimen, joka avaa seuraavan paikan: tähtikaton, kuistin meren rannalla, kitaran ja päiväkirjan, hengityshuoneen, metsäpolun joogan kera, vesiputouksen ja yllätyksen katolla – ja 8. tuo merestä pullon, jonka sisällä on kirje menneisyydestä. Kun jotain aukeaa, nuoli näyttää tien. Pelikoneen alareunan pieni luukku aukeaa myös – sen takana oleva kaappi on toistaiseksi tyhjä. Tähtikatolla napautettu tähti putoaa kuin tähdenlento, ja kissa istuu tyynyllä.",
