    faq_a_home_focus: "Napauta ◎ aloitusnäytön yläreunassa: kaikki katoaa paitsi se yksi asia nyt – mitä tällä tunnilla on, tai seuraava asia tämän päivän listalla – ison ✓:n kanssa, sekä Pika-muistiinpano. ✓:n jälkeen näkyviin tulee seuraava asia. Napauta ylhäällä 'Keskittymistila ✕', niin kaikki palaa.",
    faq_a_home_search: "Avaa valikko ☰ – haku on ihan ylhäällä. Kirjoita vähintään 2 kirjainta: tulokset tulevat muistiinpanoistasi, ostoslistasta, kalenterista, resepteistä, vihoista (otsikot ja sivujen teksti), tavoitteista, taulukoista ja kirjoista tyypeittäin ryhmiteltyinä – napauta tulosta siirtyäksesi suoraan siihen.",
    faq_a_my_day: "Päiväni yhdistää sen, mikä ennen oli Silmäys Tähän Päivään ja Rutiinini, yhdelle aikajanalle. Aloitusnäytön alareunassa näet, paljonko on tehty, mitä on nyt tai seuraavaksi (pikamerkinnällä ✓) ja otsikon vieressä lasin vettä +1:llä. Napauta sitä (tai pyyhkäise ylös), niin koko päivä aukeaa: ylhäällä asiat ilman kellonaikaa, sitten kaikki tunneittain – kalenterin tehtävät, tapahtumat ja tapaamiset, viikon kiinteät ajat, tämän päivän rutiini, tavoitteidesi pienet askeleet ja New Me -ateriat – sekä viiva nykyhetkelle. Suodata valinnalla Tehtävät, Rutiini tai Tapaamiset ja tapahtumat. Täällä tehty ✓ on sama ✓ kuin kaikkialla muualla (Rutiinini, Omat Tavoitteet, kalenteri), ja se avaa päivänkakkaran nurkkaukseen. 'Muokkaa rutiinia' avaa Rutiinini (se on myös valikossa), ja '＋ Lisää tälle päivälle' lisää tehtävän tälle päivälle. ”Päiväni”-otsikon (tai yläreunan pienen palkin) napautus sulkee sen taas.",
