    faq_a_new_me_tour: "Heti oston ja lyhyen kyselyn jälkeen lyhyt esittely näyttää pelin: yläpalkin, seuraavan tehtävän, viikon haasteen, taikarepun ja oven 1 salaiseen huoneeseen. Sen voi katsoa uudelleen milloin tahansa kohdasta ⚙️ Asetukset > 🧭 New Me -esittely – siellä voi myös muuttaa kyselyssä annetun koko nimen. Ennen ostoa New Me -kohdassa näkyy valikossa 🔒, ja sen napauttaminen avaa sivun, jolla on kaikki, mitä ohjelmaan sisältyy.",
