    faq_a_new_me_advanced: "Edistynyt tila aukeaa lahjan mukana, kaikkien 20 haasteen jälkeen, ja sen voi kytkeä päälle tai pois kohdassa 🎁 Lahjasi. Se antaa New Me -ohjelmalle kultaisen ulkoasun, vapaan ruokalistan kokoamisen – jokainen vaihto näyttää kaikki vaihtoehdot ilman kalorirajaa – ja näkymän 📊 Tarkemmat tilastot: viimeisten 30 päivän kalorit suunnitelmaan verrattuna, hyvät päivät viikonpäivittäin, painon suunta ja arvio tavoitteen saavuttamisesta, iltakatsausten keskiarvot sekä haasteiden historia.",
