    nm_gift_intro: "Kaikki {n} haastetta, askel kerrallaan. Tämä odotti:",
    nm_gift_title: "Lahjasi",
    faq_a_new_me_letter_gift: "New Me -ohjelman alussa (tai myöhemmin Haasteissa) voi kirjoittaa kirjeen itselle tulevaisuuteen. Sinetöinnin jälkeen sitä ei voi lukea eikä muokata ennen kuin se avautuu: salaisen huoneen merestä tulleessa pullossa tai kaikkien 20 haasteen lopussa – jossa odottaa myös lahja.",
    faq_q_new_me_letter_gift: "Mikä on kirje menneisyydestä?",
    faq_a_new_me_challenges: "🏆 Haasteet sisältää 20 haastetta: 10 isoa (kuten 5 päivää ilman sokeria, viikko ilman hiilihydraatteja tai 4 kg pois kuukaudessa – joka päivä kalorivaje, treeni ja ilman sokeria) ja 10 minihaastetta – pieniä tapoja viikon ajan, kuten kanelikahvi ilman sokeria. Haastetta valittaessa kysytään, milloin aloitetaan: tänään, huomenna, ensi viikolla vai muuna päivänä. Yksi iso ja yksi minihaaste voivat olla käynnissä yhtä aikaa. Käynnissä oleva haaste näkyy ruokalistan ylimpänä ja Päiväni-osiossa, päivän ✓-merkin kanssa. Jokainen haasteviikko tuo yhden vapaapäivän (🍕), joka ei katkaise haastetta, ja merkitsemätön päivä lasketaan vapaapäiväksi – tämän päivän ja eilisen voi merkitä. Osa päivistä merkitään itsestään: 20 minuutin treeni Treenien Seurannassa tai ruokalistan ateriat ✓-merkillä. Jokaisessa haasteessa on ⓘ siitä, mikä tarkalleen lasketaan (esimerkiksi koko hiilihydraattilista) – itse haasteessa ja sen vieressä Päiväni-näkymässä. Niiden alla kohdassa 🌱 Henkilökohtainen kasvu on 48 pientä viikon haastetta (ne eivät kuulu näihin 20:een) – katso ”Mikä on viikon haaste?”.",
    faq_q_new_me_challenges: "Miten New Me -haasteet toimivat?",
    nm_letter_too_short: "Vielä muutama sana 🙂",
    nm_letter_quiz_note: "Vapaaehtoinen – sen voi kirjoittaa myöhemminkin, Haasteet-osiossa.",
    nm_letter_write: "✍️ Kirjoita kirje",
    nm_letter_sealed_line: "Sinetöity {date} · avautuu {n} haasteen jälkeen",
    nm_letter_sealed_toast: "Sinetöity ✉️ – nähdään maalissa",
    nm_letter_seal_note: "Kun kirje on sinetöity, sitä ei voi lukea eikä muokata ennen kuin kaikki haasteet on suoritettu.",
    nm_letter_seal: "✉️ Sinetöi kirje",
    nm_letter_ph: "Missä olen tänään, mihin haluan päästä, mikä on minulle vaikeaa ruoan kanssa, mitä haluaisin sanoa itselleni maalissa…",
    nm_letter_intro: "Kirjoitetaan nyt ja sinetöidään – avautuu vasta kaikkien {n} haasteen jälkeen, jotta näkee, kuinka paljon on muuttunut. Missä olen nyt? Mitkä ovat tavoitteeni, ja mikä on minulle vaikeaa ruoan kanssa?",
