    nm_ch_menu_21_desc: "Joka päivä ruokalistan ateriat saavat ✓ – vähintään 3, tai kaikki, jos ruokalista on pienempi. Suunniteltu vapaa ateria lasketaan, ja päivä merkitään itsestään.",
    nm_ch_menu_21_title: "21 päivää ruokalistan mukaan",
    nm_ch_no_sugar_21_desc: "Kolme viikkoa ilman lisättyä sokeria – tarpeeksi aikaa makeanhimon rauhoittumiseen. Hedelmät ja luonnollinen makeus käyvät.",
