    nm_ch_no_snacking_14_desc: "Vain se, mitä ruokalistalla on, ja juomat – ei napostelua aterioiden välillä. Nälkä? Lasi vettä tai teetä, ja seuraava ateria on lähellä.",
    nm_ch_no_snacking_14_title: "Kaksi viikkoa ilman napostelua",
