    nm_ch_sport_14_task: "20 minuuttia liikettä",
    nm_ch_sport_14_desc: "Vähintään 20 minuuttia liikettä päivässä – kävelykin lasketaan. Treenien Seurantaan kirjattu treeni merkitsee päivän itsestään.",
