    nm_ch_deficit_14_desc: "Joka päivä ohjelman kaloribudjetin sisällä – treenit kasvattavat sitä. New Me -näkymän rengas näyttää, paljonko on jäljellä.",
    nm_ch_deficit_14_title: "Kaksi viikkoa kalorivajeessa",
    nm_ch_no_carbs_7_task: "Päivä ilman hiilihydraatteja",
    nm_ch_no_carbs_7_desc: "Viikko ilman hiilihydraatteja – jokaisella aterialla lisäkasvikset ja proteiini tulevat hiilihydraatin tilalle. Mikä lasketaan hiilihydraatiksi? Koko lista löytyy ⓘ:n alta.",
