    nm_ch_rule: "Yksi vapaapäivä jokaista haasteviikkoa kohden. Merkitsemätön päivä lasketaan vapaapäiväksi – tämän päivän ja eilisen voi merkitä. Yksi iso ja yksi minihaaste voivat olla käynnissä yhtä aikaa.",
