    nm_tile_challenges: "Haasteet",
    faq_a_workout_calories: "Lasketaan. Jokaisesta treenistä tehdään arvio kulutetuista kaloreista – lajin, keston ja viimeisimmän painosi perusteella (juoksussa ja pyöräilyssä myös vauhdin mukaan, kun matka on syötetty). Se näkyy treenilistassa ja kuukausikoosteessa (Kulutettu), ja se lisätään sen päivän kaloribudjettiin: Päivittäisessä Ateriaseurannassa, Kalori- ja painomittareissa ja New Men renkaassa. Se on arvio, siksi siinä on ~.",
    faq_q_workout_calories: "Lasketaanko treenit päivän kaloreihin?",
    faq_a_new_me_flexible_menu: "Kyllä. Kyselyssä ja asetuksissa valitaan, montako ateriaa päivässä – 2 ateriaa + välipala / 2 ateriaa + kevyt illallinen / 2 ateriaa + välipala + kevyt illallinen – ja aterian kortin ➖ poistaa sen (vähintään 3 jää); ”➕ Palauta” tuo sen takaisin. Joka tapauksessa päivän kalorit pysyvät samoina: pois jäävä jaetaan muille aterioille, ja jokaisen aterian alla näkyy, paljonko siihen lisättiin ja mitä siihen sopii. Aterian ✏️ Muokkaa avaa sen tekstin – muuta mitä haluat (esim. ilman leipää tai yhdellä munalla lisää), ja tekoäly laskee kalorit ja proteiinin uudelleen. 🔄 Vaihda tarjoaa vaihtoehtoja ruokalistalta, ⭐ Tallennetut ja ✨ Kirjoita itse; jokainen muutos voi koskea vain tätä päivää tai tästä eteenpäin. Ja ”Koko päivä” -näkymän lopussa on ➕ Lisää ruokaa – kirjoita, mitä syötiin ruokalistan ulkopuolella, niin tekoäly laskee sen ja lisää tähän päivään (✕ poistaa).",
    faq_q_new_me_flexible_menu: "Voinko muuttaa aterioiden määrää New Me -ohjelmassa tai syödä oman aterian?",
