    nm_sales_f6: "Automaattinen ostoslista ruokalistasta sekä ateriamuistutukset",
    nm_sales_f5: "Älykkäät vaihdot – ruokalistalta, tallennetuista aterioista tai tekoälyllä kirjoitettuna",
    nm_story_outro_text: "Ei yksi täydellinen päivä – vaan monta hyvää päivää. Askel kerrallaan.",
