    nm_story_control_text: "Valmista se kotona tarkoista aineksista ja tallenna se sovellukseen tallennetuksi ateriaksi – ensi kerralla se on yksi napautus.",
    nm_story_control_title: "Täysi hallinta",
    nm_story_estimate_text: "Samanlainen annos tietokannan ”ulkona syöminen” -kategoriasta antaa hyvän keskimääräisen arvion.",
    nm_story_estimate_title: "Etkö ole varma? Valitse samanlainen annos",
    nm_story_out_text: "Nuudelit + kananrinta + lusikallinen öljyä + kastike: kun kirjaat jokaisen osan erikseen, arvio on paljon parempi.",
    nm_story_out_title: "Syötkö ulkona? Pilko osiin",
    nm_story_weekly_text: "Keho toimii viikon keskiarvon mukaan, ei yksittäisen päivän. Ei tarvitse korvata eikä jättää aterioita väliin – jatka vain tavalliseen tapaan.",
    nm_story_weekly_title: "Menikö yli? Ei stressiä",
    nm_story_after_text: "Valitse vain tietokannasta kypsennetty versio – esimerkiksi ”keitetty valkoinen riisi”, ei ”kuiva riisi”.",
    nm_story_after_title: "Punnitsetko kypsennyksen jälkeen? Sekin on hienoa",
    nm_story_pot_text: "Punnitsitko ja laskit koko kattilan etukäteen? Jaa valmis ruoka tasakokoisiin annoksiin – ei tarvitse punnita uudelleen.",
    nm_story_pot_title: "Jaa kattila silmämääräisesti",
    nm_story_raw_text: "Raa'alla ruoalla on vakioarvot – kypsennys muuttaa vain sen vesimäärää. Kun punnitset ensin, jokainen resepti pysyy tarkkana.",
