    vision_tagline: "Isot tavoitteet, pienet askeleet.",
    faq_a_app_tour: "Kierros avautuu automaattisesti kerran, kun tulet sovellukseen ensimmäistä kertaa. Se alkaa osistaan – napauta yhtä siirtyäksesi suoraan siihen – ja näyttää sitten sovelluksen kaikki osat (aloitusnäytön, tekoälyavustajan ja jokaisen valikon kohdan) sekä Asetusten viisi ryhmää, jokaisen lyhyen selityksen kera, ja kurkistaa joidenkin sisään (esimerkiksi esimerkkipolkuun tavoitteelle, laukkuun sekä Google Calendariin). Jatka vie eteenpäin, Takaisin palaa taaksepäin, Ohita tämä osa siirtyy seuraavaan osaan ja ✕ sulkee kierroksen. Voit katsoa sen uudelleen milloin tahansa kohdasta Asetukset > Ohje ja käyttö > Sovelluskierros ja jatkaa siitä, mihin jäit. Jatka ja Takaisin ovat aina samassa kohdassa näytön alareunassa, ja tietokoneella toimivat myös nuolinäppäimet.",
    faq_q_app_tour: "Miten näen sovelluskierroksen uudelleen?",
