    table_select_option_delete_title: "Poista vaihtoehto",
    faq_a_other_manual_option: "Kaikkialla, missä valitset vaihtoehtoluettelosta, on myös '✏️ Muu' - valitse se ja kirjoita juuri se, mitä tarvitset. Taulukossa, jossa on valintasarake (esimerkiksi 'Sukulaisuus' lahjataulukossa), napauta solua, valitse '✏️ Muu', kirjoita arvo (esimerkiksi 'Veljenpoika') ja napauta Lisää - se tallentuu sarakkeen uudeksi vaihtoehdoksi, joten ensi kerralla se on jo luettelossa. Luettelon jokaisen vaihtoehdon vieressä oleva pieni × poistaa vaihtoehdon sarakkeesta. Taulukon kuvaketta valittaessa tarjolla on paljon kuvakkeita (myös värikkäitä muistilappuja). Sama toimii tallennettujen aterioiden kategorioissa, reseptikategorioissa, toistuvien menojen kategorioissa (tallentuu uudeksi omaksi kategoriaksi) ja tavoitekategorioissa kohdassa Omat Tavoitteet.",
