    receipts_total_title: "Kaikkien kuittien summa",
    receipts_total_tile: "Kaikkien kuittien summa",
    faq_a_quick_note_apple: "Muistiinpanoikkunassa 📝:n ja 🛒:n vieressä oleva 🍎 on pikakuvake, jolla voit nopeasti kirjata jonkin tallennetuista aterioistasi tämän päivän Päivittäinen Ateriaseuranta -näkymään. Se on oletuksena käytössä - jos et tarvitse sitä, voit poistaa sen käytöstä kohdassa Asetukset > Mukauttaminen ja kalenteri ('Näytä tallennettujen aterioiden 🍎-pikakuvake muistiinpanoikkunassa') ja ottaa sen samassa paikassa takaisin käyttöön milloin tahansa.",
    faq_q_quick_note_apple: "Mikä on muistiinpanoikkunan 🍎, ja voiko sen piilottaa?",
    settings_quick_note_apple_label: "Näytä tallennettujen aterioiden 🍎-pikakuvake muistiinpanoikkunassa",
    faq_a_vision_board_today: "Napauta kohdassa Omat Tavoitteet tavoitteen polun alla (kohdassa 'Suunnitelma') vaiheen vieressä olevaa 📅-painiketta ja valitse päivämäärä. Voit myös ottaa käyttöön valinnan '🔁 Joka viikko, kunnes tehty' – silloin vaihe palaa joka viikko samana päivänä, kunnes merkitset sen kerran tehdyksi. Vaihe näkyy valittuna päivänä kohdassa Päiväni ja kalenterissa (ja myös Google Calendarissa, jos se on yhdistetty), ja painike näyttää, milloin se on ajoitettu. ✓-merkintä yhdessä paikassa merkitsee sen myös toisessa ja vie tavoitteen polkua eteenpäin. Napauta 📅-painiketta uudelleen, jos haluat muuttaa päivämäärää tai poistaa vaiheen kalenterista. Kertaluonteisen tehtävän poistaminen kalenterista poistaa myös vaiheen tavoitteesta; viikoittaisen muistutuksen yhden viikon poistaminen poistaa vain sen viikon.",
    faq_q_vision_board_today: "Miten lisään tavoitteen vaiheen kalenteriin (📅)?",
    vision_milestone_already_today: "Tämä vaihe on jo tämän päivän tehtävissä.",
    auth_consent_required: "Rekisteröityminen edellyttää Käyttöehtojen ja Tietosuojakäytännön hyväksymistä.",
