    nm_extras_title: "Tänään syöty myös",
    nm_drinks_total: "{n} / ~{kcal} kcal",
    nm_drink_missing: "Anna juoman nimi ja kalorit",
    nm_drink_more: "+ Uusi juoma",
    nm_drink_add: "Lisää",
    nm_drink_name_ph: "Juoma (esim. mehu)",
    nm_drinks_hint: "Kirjoita vain juoman nimi – kalorit lasketaan automaattisesti, ja lukua voi muuttaa.",
    nm_slot_drinks: "Juomat",
    faq_a_new_me_tracking: "Napauta New Me -ohjelman yläreunan seuraavaa tehtävää ja sitten ✓ Söin merkitäksesi seuraavan aterian syödyksi – koko ruokalista ✓:n kera jokaisen aterian kohdalla on Koko päivä -näkymässä, sivussa, ja tämän päivän ateriat näkyvät myös aloitusnäytön Päiväni-näkymässä – siellä aterian napauttaminen (tai hiiren vieminen sen päälle) näyttää tarkalleen, mitä syödään, ✓:n ja Vaihda-painikkeen kera. Kaikki synkronoidaan Päivittäiseen Ateriaseurantaan: ohjelman ateriat, juomat ja kaikki muualla lisäämäsi (esim. kahvi pikalisäyksestä) lasketaan yhteen New Me -ohjelmassa ja Päiväni-näkymässä – mitään jo kirjoittamaasi ei kirjoiteta yli, ja ✓:n poistaminen poistaa vain New Me -osuuden. Kun kaikki tämän päivän ateriat on merkitty, tulee pieni juhlahetki. ”Juomat”-kohtaan kirjataan päivän juomat – yhteensä enintään ~150 kcal eli noin 3 juomaa, kukin enintään ~50 kcal. Kirjoita vain juoman nimi, niin tekoäly täyttää kalorit automaattisesti. Kahdella kahvi/tee-rivillä on myös kenttä ”Maitoa? Kuinka paljon?” (esim. ”vähän” tai ”50 ml”), ja laskelma päivittyy; lukua voi muuttaa sekä ennen lisäämistä että sen jälkeen. Juoma, jolla on nimi ja kalorit, tallentuu automaattisesti heti, kun siirryt eteenpäin – Lisää-painikkeen napauttaminen on vapaaehtoista. Napauta ☆ juoman vieressä tallentaaksesi sen vakiojuomaksi – vakiojuomat näkyvät painikkeina Juomat-kortin yläosassa, ja yksi napautus lisää ne päivään. ⭐ tallentaa aterian tallennetuksi ateriaksi. ”Päivätaulukko” näyttää, mitä söit, kalorien ja proteiinin kera. Pieni 💎 keskittymistilan vieressä aloitusnäytön yläreunassa avaa sen suoraan. Kalori- ja proteiiniarvot ovat tekoälyn arvioita ja voivat sisältää virheitä. Jäikö jotain syömättä? Merkityn aterian alla ”Jäikö jotain syömättä?” vähentää neljänneksen, puolet tai kolme neljännestä annoksesta – tai sen, mitä kirjoitat, laskettuna – ja päivän kalorit päivittyvät.",
    faq_q_new_me_tracking: "Miten ✓, vaihdot ja kalorit toimivat New Me:ssä?",
    faq_a_new_me_what: "New Me on erillinen päivittäisen ruokalistan ohjelma, jossa on kaksi valmista suunnitelmaa – 1 300 tai 1 500 kaloria – 2 pääateriasta ja 2 välipalasta, kuhunkin 3 vaihtoehtoa. Siihen sisältyy koko Premium. Hinta: $11.99 kuukaudessa (peru milloin tahansa) tai kertamaksu $99.99, elinikäinen. Se avataan valikon kohdasta 💎 New Me. Ennen aloitusta on lyhyt kysely, joka alkaa hyväksyttävällä lääketieteellisellä vastuuvapauslausekkeella. Ohjelma on vain yleistä tietoa eikä korvaa lääkäriä tai kliinistä ravitsemusterapeuttia.",
    faq_q_new_me_what: "Mikä New Me on ja miten saan sen?",
