    faq_q_daily_focus_prompt: "Mikä on se pieni muistutus, joka kysyy, mikä on minulle tänään tärkeintä tehdä?", faq_a_daily_focus_prompt: "Se on päivittäinen Premium-muistutus: kerran päivässä AI-avustajan kuvakkeeseen ilmestyy pieni ”1”-merkki. Napauta merkkiä, niin avautuu kupla, joka kysyy, mikä on sinulle tänään tärkeintä tehdä, ja siinä näkyy heti 5 valmista ehdotusta (ne vaihtuvat päivittäin ja kiertävät kokonaisen vuoden verran eri teemoja, jotta ne pysyvät tuoreina) sekä 'Muu', jolla voit kirjoittaa omasi - voit valita useamman. Napauta Lisää, niin valintasi näkyvät pieninä muistutustunnisteina 'Päiväni' -näkymän yläreunassa (ne eivät ole merkittäviä tehtäviä). Jos suljet sen ✕:llä tai napautat sen ulkopuolelle, merkki vain himmenee loppupäiväksi katoamisen sijaan. Se on oletuksena päällä, mutta voit poistaa sen käytöstä kohdassa Asetukset > Mukauttaminen ja kalenteri. Eikö tänään ole oikea päivä? Napauta '🌙 Ei tänään' – merkki katoaa huomiseen asti, ja sitten kysymys palaa tavalliseen tapaan. Yksi ehdotuksista tulee omasta elämästäsi – kuukauden tavoitteen seuraava askel tai päivän lukeminen. Jokainen päivä alkaa puhtaalta pöydältä.",
